import { createRoute, z } from '@hono/zod-openapi'

const XmlStringMaxLen255Schema = z
  .string()
  .min(1)
  .max(255)
  .openapi({
    'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
  })
  .openapi('XmlStringMaxLen255')

const XmlStringMaxLen32Schema = z
  .string()
  .min(1)
  .max(32)
  .openapi({
    'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
  })
  .openapi('XmlStringMaxLen32')

const LaunchTemplateNameSchema = z
  .string()
  .regex(/[a-zA-Z0-9\(\)\.\-\/_]+/)
  .min(3)
  .max(128)
  .openapi('LaunchTemplateName')

const LaunchTemplateSpecificationSchema = z
  .object({
    LaunchTemplateId: XmlStringMaxLen255Schema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The ID of the launch template. To get the template ID, use the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplates.html">DescribeLaunchTemplates</a> API operation. New launch templates can be created using the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplate.html">CreateLaunchTemplate</a> API. </p> <p>Conditional: You must specify either a <code>LaunchTemplateId</code> or a <code>LaunchTemplateName</code>.</p>',
        }),
    ).exactOptional(),
    LaunchTemplateName: LaunchTemplateNameSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The name of the launch template. To get the template name, use the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplates.html">DescribeLaunchTemplates</a> API operation. New launch templates can be created using the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplate.html">CreateLaunchTemplate</a> API. </p> <p>Conditional: You must specify either a <code>LaunchTemplateId</code> or a <code>LaunchTemplateName</code>.</p>',
        }),
    ).exactOptional(),
    Version: XmlStringMaxLen255Schema.and(
      z
        .any()
        .openapi({
          description:
            'The version number, <code>$Latest</code>, or <code>$Default</code>. To get the version number, use the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplateVersions.html">DescribeLaunchTemplateVersions</a> API operation. New launch template versions can be created using the Amazon EC2 <a href="https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplateVersion.html">CreateLaunchTemplateVersion</a> API. If the value is <code>$Latest</code>, Amazon EC2 Auto Scaling selects the latest version of the launch template when launching instances. If the value is <code>$Default</code>, Amazon EC2 Auto Scaling selects the default version of the launch template when launching instances. The default value is <code>$Default</code>.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Describes the launch template and the version of the launch template that Amazon EC2 Auto Scaling uses to launch Amazon EC2 instances. For more information about launch templates, see <a href="https://docs.aws.amazon.com/autoscaling/ec2/userguide/LaunchTemplates.html">Launch templates</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.',
    required: [],
  })
  .openapi('LaunchTemplateSpecification')

const NullablePositiveIntegerSchema = z.int().min(0).openapi('NullablePositiveInteger')

const VCpuCountRequestSchema = z
  .object({
    Min: NullablePositiveIntegerSchema.and(
      z.any().openapi({ description: 'The minimum number of vCPUs.' }),
    ),
    Max: NullablePositiveIntegerSchema.and(
      z.any().openapi({ description: 'The maximum number of vCPUs.' }),
    ).exactOptional(),
  })
  .openapi({
    required: ['Min'],
    description:
      'Specifies the minimum and maximum for the <code>VCpuCount</code> object when you specify <a>InstanceRequirements</a> for an Auto Scaling group.',
  })
  .openapi('VCpuCountRequest')

const MemoryMiBRequestSchema = z
  .object({
    Min: NullablePositiveIntegerSchema.and(
      z.any().openapi({ description: 'The memory minimum in MiB.' }),
    ),
    Max: NullablePositiveIntegerSchema.and(
      z.any().openapi({ description: 'The memory maximum in MiB.' }),
    ).exactOptional(),
  })
  .openapi({
    required: ['Min'],
    description:
      'Specifies the minimum and maximum for the <code>MemoryMiB</code> object when you specify <a>InstanceRequirements</a> for an Auto Scaling group.',
  })
  .openapi('MemoryMiBRequest')

const CpuManufacturerSchema = z
  .enum(['intel', 'amd', 'amazon-web-services'])
  .openapi('CpuManufacturer')

const CpuManufacturersSchema = z.array(CpuManufacturerSchema).openapi('CpuManufacturers')

const NullablePositiveDoubleSchema = z.float64().min(0).openapi('NullablePositiveDouble')

const MemoryGiBPerVCpuRequestSchema = z
  .object({
    Min: NullablePositiveDoubleSchema.and(
      z.any().openapi({ description: 'The memory minimum in GiB.' }),
    ).exactOptional(),
    Max: NullablePositiveDoubleSchema.and(
      z.any().openapi({ description: 'The memory maximum in GiB.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Specifies the minimum and maximum for the <code>MemoryGiBPerVCpu</code> object when you specify <a>InstanceRequirements</a> for an Auto Scaling group.',
    required: [],
  })
  .openapi('MemoryGiBPerVCpuRequest')

const ExcludedInstanceSchema = z
  .string()
  .regex(/[a-zA-Z0-9\.\*\-]+/)
