const InstanceGenerationSchema = z.enum(['current', 'previous']).openapi('InstanceGeneration')

const InstanceGenerationsSchema = z.array(InstanceGenerationSchema).openapi('InstanceGenerations')

const BareMetalSchema = z.enum(['included', 'excluded', 'required']).openapi('BareMetal')

const BurstablePerformanceSchema = z
  .enum(['included', 'excluded', 'required'])
