export const getActionAttachInstancesRoute = createRoute({
  method: 'get',
  path: '/#Action=AttachInstances',
  description:
    '<p>Attaches one or more EC2 instances to the specified Auto Scaling group.</p> <p>When you attach instances, Amazon EC2 Auto Scaling increases the desired capacity of the group by the number of instances being attached. If the number of instances being attached plus the desired capacity of the group exceeds the maximum size of the group, the operation fails.</p> <p>If there is a Classic Load Balancer attached to your Auto Scaling group, the instances are also registered with the load balancer. If there are target groups attached to your Auto Scaling group, the instances are also registered with the target groups.</p> <p>For more information, see <a href="https://docs.aws.amazon.com/autoscaling/ec2/userguide/attach-instance-asg.html">Attach EC2 instances to your Auto Scaling group</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>',
  operationId: 'GET_AttachInstances',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      InstanceIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(XmlStringMaxLen19Schema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'InstanceIds',
            in: 'query',
            required: false,
            description: 'The IDs of the instances. You can specify up to 20 instances.',
            schema: { type: 'array', items: { $ref: '#/components/schemas/XmlStringMaxLen19' } },
          },
        }),
      AutoScalingGroupName: z
        .string()
        .min(1)
        .max(255)
        .openapi({
          param: {
            name: 'AutoScalingGroupName',
            in: 'query',
            required: true,
            description: 'The name of the Auto Scaling group.',
            schema: {
              type: 'string',
              minLength: 1,
              maxLength: 255,
              'x-pattern':
                '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
            },
          },
          'x-pattern': '[\\u0020-\\uD7FF\\uE000-\\uFFFD\\uD800\\uDC00-\\uDBFF\\uDFFF\\r\\n\\t]*',
        }),
      Action: z
        .literal('AttachInstances')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['AttachInstances'] },
          },
        }),
      Version: z
        .literal('2011-01-01')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2011-01-01'] },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Success' },
    480: {
      description: 'ResourceContentionFault',
      content: { 'text/xml': { schema: ResourceContentionFaultSchema } },
    },
    481: {
      description: 'ServiceLinkedRoleFailure',
      content: { 'text/xml': { schema: ServiceLinkedRoleFailureSchema } },
    },
  },
})

